'use client';
import { useState } from 'react';
import { useI18n } from '@/lib/i18n/client';
import { fmt } from '@/lib/i18n/config';
import { Icon } from '@/components/ui/Icon';
import { useAiFlags, useAiJob } from '@/components/ai/useAiJob';

/**
 * AI promotional picture for Image Studio (flag `ai_social_images`, off by default). The picture is generated by the
 * worker without text in the pixels, stored privately with provenance, and only added to the photos when the
 * customer chooses it; headlines and prices stay editable text layers.
 */
export function AiImageJob({ language, aspect, purpose, initialPrompt, disabled, onUse }: { language: string; aspect: string; purpose: string; initialPrompt: string; disabled: boolean; onUse: (asset: { id: string; url: string | null }) => void }) {
  const { t } = useI18n();
  const c = t.aiContent;
  const flags = useAiFlags();
  const job = useAiJob();
  const [prompt, setPrompt] = useState(initialPrompt);
  if (!flags) return null;
  if (!flags.images) return <p className="xsmall muted" data-testid="ai-image-disabled"><Icon name="info" /> {c.imageNotEnabled}</p>;
  const file = job.job?.status === 'completed' ? job.job.files[0] : undefined;
  const failed = job.job?.status === 'failed' ? job.job.error_code : job.error;
  return (
    <div className="stack-sm" data-testid="ai-image">
      <label className="field">
        <span className="field-label xsmall">{c.imagePrompt}</span>
        <textarea className="textarea" rows={2} maxLength={2000} value={prompt} onChange={(e) => setPrompt(e.target.value)} dir="auto" disabled={disabled} />
      </label>
      <div>
        <button type="button" className="btn btn-sm" disabled={disabled || job.busy || !prompt.trim()} onClick={() => void job.request('social_image', { language: ['en', 'fr', 'ar', 'de'].includes(language) ? language : 'en', prompt, aspect: ['1:1', '4:5', '9:16', '16:9'].includes(aspect) ? aspect : '1:1', purpose })} data-testid="ai-image-generate">
          <Icon name="sparkle" /> {job.busy ? c.generating : c.imageGenerate}
        </button>
      </div>
      {job.busy && <p className="xsmall muted">{c.queued}</p>}
      {failed && <p className="callout callout-danger small" role="alert">{fmt(c.failed, { code: String(failed) })}</p>}
      {file && (
        <div className="row" data-testid="ai-image-result">
          {file.url && <img src={file.url} alt="" width={96} height={96} style={{ objectFit: 'cover', borderRadius: 8 }} />}
          <div className="stack-sm">
            <span className="badge plain">{file.mock ? t.animation.mock : t.animation.ai}</span>
            <span className="xsmall muted">{c.provenance}</span>
            <button type="button" className="btn btn-sm btn-primary" onClick={() => onUse({ id: file.id, url: file.url })} disabled={disabled}>{c.imageUse}</button>
          </div>
        </div>
      )}
    </div>
  );
}
